"""Focused census parser tests for Black (USA) PS2 inventory structures.
Fixtures: exact leading bytes from the owned SLUS_213.76 extraction
(disc sha256 65768cade88bfbaf566b67a3ef7a0bda5a9669779833914ffe7cd73a3e45cccd).
"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "gbox", "ps2_black_usa"))
from trans_census import parse_name_table, parse_unit_container_header, parse_ak_header

TRANS_CH = bytes.fromhex("")
UNIT_01 = bytes.fromhex("1800000000145300b0745d00d0536d00000000000000000000000000a0000000d01e6e007006000020098900b08a8900c0f04e0090fd520070095300800c5300")
ANDY_AKU = bytes.fromhex("020000002a0500000000000015000000702900000000803fec7b28800000c84230442c8000007042e4a03d8000000000bd64c0800000803f05c3c880cdcc4c3f9ad4e0800000803f57a0f9800ad7a33e")
TRANS_FP = bytes.fromhex("25000000100000000003000030030000b0000000c0000000d0000000e0000000f000000000010000100100002001000030010000400100005001000060010000700100008001000090010000a0010000b0010000c0010000d0010000e0010000")

def test_trans_ch_name_registry():
    r = parse_name_table(TRANS_CH)
    assert r["count"] == 161
    assert r["stride"] == 0x10
    assert r["record_offset"] == 0x2A0
    assert r["names"][0] == "I_030"
    assert r["names"][1] == "I_031"
    assert r["names"][2] == "S_102"
    assert r["names"][3] == "S_103"
    for n in r["names"][:12]:
        assert n and all(32 <= ord(c) < 127 for c in n)
    # 161 records x 0x10 stride ends exactly at the name-table offset 0xCB0.
    assert 0x2A0 + 161 * 16 == 0xCB0

def test_trans_fp_name_registry():
    r = parse_name_table(TRANS_FP, record_offset=0x10)
    assert r["count"] == 37
    assert r["stride"] == 0x10

def test_unit_01_container_header():
    r = parse_unit_container_header(UNIT_01)
    assert r["count"] == 24
    assert r["first_offsets"] == [0x531400, 0x5D74B0, 0x6D53D0]

def test_andy_ak_header():
    assert parse_ak_header(ANDY_AKU) == {"blocks": 2, "block1_offset": 0x52A,
                                         "reserved": 0, "units": 21,
                                         "payload_size": 0x2970}

def test_roundtrip_names():
    r = parse_name_table(TRANS_CH)
    # The TRANS_CH fixture is deliberately truncated to its header + the first
    # name records; round-trip every record the parser actually decoded.
    for i in range(len(r["names"])):
        rec = TRANS_CH[0x2A0 + i*16: 0x2A0 + (i+1)*16]
        assert r["names"][i].encode().ljust(16, b"\x00")[:16] == rec

if __name__ == "__main__":
    for name, fn in sorted(globals().items()):
        if name.startswith("test_") and callable(fn):
            fn(); print("PASS", name)
    print("ALL PASS")
